          volume: 0.8,
          enabled: true,
          position: 0,
          songIntro: { songId: 100, programId: PROGRAM },
        },
        {
          id: 2,
          name: 'Jingle',
          audioUrl: SIGNED,
          volume: 1,
          enabled: false,
          position: 1,
          songIntro: null,
