    });
  });
});

import { BadRequestException } from '@nestjs/common';
import { MediaAssetKind, MediaAssetType } from '@prisma/client';
import { SongsService } from './songs.service';

function buildService() {
  const tx = {
    song: {
      findUnique: jest.fn(),
      findUniqueOrThrow: jest.fn(),
      update: jest
        .fn()
        .mockImplementation(({ data }: { data: Record<string, unknown> }) =>
          Promise.resolve({ ...song, ...data }),
        ),
      create: jest.fn(),
    },
    programState: { findUnique: jest.fn() },
    instant: { findUnique: jest.fn() },
    songIntro: {
      findUnique: jest.fn(),
      upsert: jest.fn(),
      delete: jest.fn(),
    },
    mediaAsset: { upsert: jest.fn(), deleteMany: jest.fn() },
  };
  const prisma = {
    ...tx,
    $transaction: jest.fn((operation: (client: typeof tx) => unknown) =>
      operation(tx),
    ),
  };
  return { service: new SongsService(prisma as never), prisma, tx };
}

const song = {
  id: 7,
  artist: 'Artist',
  title: 'Song',
  audioUrl: 'https://media.test/song.mp3',
  coverUrl: null,
  durationMs: 120000,
  earoneSongId: null,
  earoneRank: null,
  earoneSpins: null,
  enabled: true,
};

describe('SongsService song intros', () => {
  it('assigns and hydrates an authoritative Instant without copying media fields', async () => {
    const { service, tx } = buildService();
    tx.song.findUnique.mockResolvedValue(song);
    tx.programState.findUnique.mockResolvedValue({ programId: 'radio' });
    tx.songIntro.findUnique
      .mockResolvedValueOnce(null)
      .mockResolvedValueOnce(null);
    tx.instant.findUnique.mockResolvedValue({
      id: 12,
      enabled: true,
      audioUrl: 'https://media.test/intro.mp3',
    });
    tx.song.findUniqueOrThrow.mockResolvedValue({
      ...song,
      intro: {
        id: 3,
        songId: song.id,
        instantId: 12,
        programId: 'radio',
        instant: {
          id: 12,
          name: 'Voice segue',
          audioUrl: 'https://media.test/intro.mp3',
          volume: 0.7,
        },
      },
    });

    const result = await service.update(song.id, {
      programId: 'radio',
      introInstantId: 12,
    });

    expect(tx.songIntro.upsert).toHaveBeenCalledWith({
      where: { songId: song.id },
      create: { songId: song.id, instantId: 12, programId: 'radio' },
      update: { instantId: 12 },
    });
    expect(tx.mediaAsset.upsert).toHaveBeenCalledWith({
      where: { id: 'song:7' },
      create: {
        id: 'song:7',
        kind: MediaAssetKind.SONG,
        mediaType: MediaAssetType.AUDIO,
        name: 'Song',
        sourceUrl: 'https://media.test/song.mp3',
        enabled: true,
      },
      update: {
        kind: MediaAssetKind.SONG,
        mediaType: MediaAssetType.AUDIO,
        name: 'Song',
        sourceUrl: 'https://media.test/song.mp3',
        enabled: true,
      },
    });
    expect(result.intro?.instant).toMatchObject({
      audioUrl: 'https://media.test/intro.mp3',
      volume: 0.7,
    });
  });

  it('removes an existing intro only from its owning program', async () => {
    const { service, tx } = buildService();
    tx.song.findUnique.mockResolvedValue(song);
    tx.programState.findUnique.mockResolvedValue({ programId: 'radio' });
    tx.songIntro.findUnique.mockResolvedValue({
      id: 3,
      programId: 'radio',
      instantId: 12,
    });
    tx.song.findUniqueOrThrow.mockResolvedValue({ ...song, intro: null });

    await service.update(song.id, {
      programId: 'radio',
      introInstantId: null,
    });

    expect(tx.songIntro.delete).toHaveBeenCalledWith({ where: { id: 3 } });
  });

  it('rejects cross-program replacement and already-assigned Instants', async () => {
    const crossProgram = buildService();
    crossProgram.tx.song.findUnique.mockResolvedValue(song);
    crossProgram.tx.programState.findUnique.mockResolvedValue({
      programId: 'television',
    });
    crossProgram.tx.songIntro.findUnique.mockResolvedValue({
      id: 3,
      programId: 'radio',
      instantId: 12,
    });
    await expect(
      crossProgram.service.update(song.id, {
        programId: 'television',
        introInstantId: 13,
      }),
    ).rejects.toThrow('Song intro belongs to another program');

    const assigned = buildService();
    assigned.tx.song.findUnique.mockResolvedValue(song);
    assigned.tx.programState.findUnique.mockResolvedValue({
      programId: 'radio',
    });
    assigned.tx.songIntro.findUnique
      .mockResolvedValueOnce(null)
      .mockResolvedValueOnce({ songId: 99, programId: 'radio' });
    assigned.tx.instant.findUnique.mockResolvedValue({
      id: 13,
      enabled: true,
      audioUrl: 'https://media.test/other.mp3',
    });
    await expect(
      assigned.service.update(song.id, {
        programId: 'radio',
        introInstantId: 13,
      }),
    ).rejects.toThrow('Instant is already assigned as a song intro');
  });

  it('rejects missing, disabled, and malformed intro identities', async () => {
    for (const [name, instantId, instant] of [
      ['malformed', -1, null],
      ['missing', 12, null],
      ['disabled', 12, { id: 12, enabled: false, audioUrl: 'url' }],
    ] as const) {
      const { service, tx } = buildService();
      tx.song.findUnique.mockResolvedValue(song);
      tx.programState.findUnique.mockResolvedValue({ programId: 'radio' });
      tx.songIntro.findUnique.mockResolvedValue(null);
      tx.instant.findUnique.mockResolvedValue(instant);
      await expect(
        service.update(song.id, {
          programId: 'radio',
          introInstantId: instantId,
        }),
      ).rejects.toBeInstanceOf(BadRequestException);
      expect(tx.songIntro.upsert).not.toHaveBeenCalled();
      expect(name).toBeTruthy();
    }
  });
});

import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Put,
  Query,
} from '@nestjs/common';
import { SongsService } from './songs.service';
import { ALCANTARA_PERMISSIONS } from '../auth/permissions';
import { RequirePermission } from '../auth/require-permission.decorator';

@Controller('songs')
@RequirePermission(ALCANTARA_PERMISSIONS.song.read)
export class SongsController {
  constructor(private readonly songsService: SongsService) {}

  @Get()
  async findAll(
    @Query('search') search?: string,
    @Query('enabled') enabled?: string,
    @Query('sortBy') sortBy?: string,
    @Query('sortOrder') sortOrder?: string,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
    @Query('programId') programId?: string,
  ) {
    return this.songsService.findAll({
      search,
      enabled: enabled === undefined ? undefined : enabled === 'true',
      sortBy,
      sortOrder,
      page: page ? Math.max(1, Number(page)) : 1,
      limit: limit ? Math.max(0, Number(limit)) : 50,
      programId,
    });
  }

  @Get(':id')
  async findOne(
    @Param('id') id: string,
    @Query('programId') programId?: string,
  ) {
    return this.songsService.findOne(Number(id), programId);
  }

  @Post()
  @RequirePermission(ALCANTARA_PERMISSIONS.song.manage)
  async create(
    @Body()
    data: {
      artist?: string;
      title?: string;
      audioUrl?: string;
      coverUrl?: string | null;
      durationMs?: number | null;
      earoneSongId?: string | number | null;
      earoneRank?: string | number | null;
      earoneSpins?: string | number | null;
      externalChartId?: string | number | null;
      externalChartSongId?: string | number | null;
      externalChartRank?: string | number | null;
      externalChartSpins?: string | number | null;
      externalChartProvider?: string | null;
      enabled?: boolean;
      programId?: string;
      introInstantId?: number | null;
    },
  ) {
    return this.songsService.create(data);
  }

  @Put(':id')
  @RequirePermission(ALCANTARA_PERMISSIONS.song.manage)
  async update(
    @Param('id') id: string,
    @Body()
    data: {
      artist?: string;
      title?: string;
      audioUrl?: string;
      coverUrl?: string | null;
      durationMs?: number | null;
      earoneSongId?: string | number | null;
      earoneRank?: string | number | null;
      earoneSpins?: string | number | null;
      externalChartId?: string | number | null;
      externalChartSongId?: string | number | null;
      externalChartRank?: string | number | null;
      externalChartSpins?: string | number | null;
      externalChartProvider?: string | null;
      enabled?: boolean;
      programId?: string;
      introInstantId?: number | null;
    },
  ) {
    return this.songsService.update(Number(id), data);
  }

  @Delete(':id')
  @RequirePermission(ALCANTARA_PERMISSIONS.song.manage)
  async remove(@Param('id') id: string) {
    return this.songsService.remove(Number(id));
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Put,
  Query,
  Req,
} from '@nestjs/common';
import { ALCANTARA_PERMISSIONS } from '../auth/permissions';
import { Public } from '../auth/public.decorator';
import { RequirePermission } from '../auth/require-permission.decorator';
import {
  MediaAssetsService,
  type MediaAssetAuthorization,
} from './media-assets.service';

type AuthorizedRequest = {
  user: { authorization: MediaAssetAuthorization };
};

@Controller()
@RequirePermission(ALCANTARA_PERMISSIONS.access)
export class MediaAssetsController {
  constructor(private readonly mediaAssets: MediaAssetsService) {}

  @Get('media-assets')
  findAll(
    @Req() request: AuthorizedRequest,
    @Query('search') search?: string,
    @Query('mediaType') mediaType?: string,
    @Query('capability') capability?: string,
    @Query('labelId') labelId?: string,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
  ) {
    return this.mediaAssets.findAll(
      {
        search,
        mediaType,
        capability,
        labelId,
        page: page ? Math.max(1, Number(page)) : 1,
        limit: limit ? Math.min(200, Math.max(1, Number(limit))) : 50,
      },
      request.user.authorization,
    );
  }

  @Get('media-assets/:id')
  findOne(@Param('id') id: string, @Req() request: AuthorizedRequest) {
    return this.mediaAssets.findOne(id, request.user.authorization);
  }

  @Post('media-assets/background-audio')
  createBackgroundAudio(
    @Body()
    body: { name?: unknown; sourceUrl?: unknown; defaultVolume?: unknown },
    @Req() request: AuthorizedRequest,
  ) {
    return this.mediaAssets.createBackgroundAudio(
      body,
      request.user.authorization,
    );
  }

  @Delete('media-assets/:id')
  removeStandaloneAsset(
    @Param('id') id: string,
    @Req() request: AuthorizedRequest,
  ) {
    return this.mediaAssets.removeStandaloneAsset(
      id,
      request.user.authorization,
    );
  }

  @Put('media-assets/:id/labels')
  replaceAssetLabels(
    @Param('id') id: string,
